import { ChangeDetectionStrategy, Component } from '@angular/core';
import { RouterLink } from '@angular/router';

@Component({
  selector: 'app-home',
  imports: [RouterLink],
  templateUrl: './home.html',
  styleUrl: './home.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class HomeComponent {}

@use '../theme/variables' as gt;

:host {
  display: block;
  max-width: gt.$max-width;
  margin: 0 auto;
  padding: 2rem 1rem;
}

.hero {
  text-align: center;
  padding: 3rem 1rem;

  &__tagline {
    font-size: 2.5rem;
    font-weight: 700;
    color: var(--gt-primary);
    margin: 0 0 1rem;
  }

  &__subtitle {
    font-size: 1.25rem;
    color: var(--gt-text);
    opacity: 0.8;
    margin: 0;
  }
}

.features {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 2rem;
  padding: 2rem 0;

  &__item {
    background: var(--gt-surface);
    border-radius: gt.$border-radius;
    padding: 1.5rem;
    border: 1px solid var(--tui-border-normal, #{gt.$neutral-light});
  }

  &__title {
    font-size: 1.25rem;
    font-weight: 600;
    color: var(--gt-primary);
    margin: 0 0 0.5rem;
  }

  p {
    color: var(--gt-text);
    margin: 0;
    line-height: 1.6;
  }
}

.cta {
  text-align: center;
  padding: 2rem 0 3rem;

  &__button {
    display: inline-block;
    background: linear-gradient(135deg, var(--gt-accent), var(--gt-accent-light));
    color: #fff;
    padding: 0.875rem 2rem;
    border-radius: gt.$border-radius;
    font-size: 1.125rem;
    font-weight: 600;
    text-decoration: none;
    transition: opacity 0.2s;

    &:hover {
      opacity: 0.9;
    }
  }
}

import { ChangeDetectionStrategy, Component } from '@angular/core';

@Component({
  selector: 'app-learn',
  template: `
    <section class="learn">
      <h2>Learn</h2>
      <p>Training exercises coming soon.</p>
    </section>
  `,
  styles: `
    :host {
      display: block;
      max-width: 1140px;
      margin: 0 auto;
      padding: 2rem 1rem;
    }
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class LearnComponent {}

