42→// This node version check ensures that extremely old versions of node are not used.
43→// These may not support ES2015 features such as const/let/async/await/etc.
44→// These would then crash with a hard to diagnose error message.
45→const [major, minor] = process.versions.node.split('.', 2).map((part) => Number(part));
